export function evidence(scenario, correction){
 const facts=scenario==='outage'?['08:10 · El personal no pudo entrar al sistema de citas.','08:40 · Se contactó al proveedor técnico. La respuesta sobre la interrupción sigue pendiente.']:['08:25 · Una empleada reportó un correo de restablecimiento desconocido.','08:40 · Se contactó al proveedor técnico. La respuesta sobre la interrupción sigue pendiente.'];
 if(correction==='checked')facts.push('Corrección del ensayo · El proveedor confirmó que el correo era legítimo.');
 return {confirmed:facts,unverified:correction==='checked'?['La lista impresa de citas podría estar disponible; recepción no la ha revisado.']:['08:25 · Origen del correo de restablecimiento sin verificar.','La lista impresa de citas podría estar disponible; recepción no la ha revisado.'],unknown:['Se desconoce si alguien accedió a los registros.','No está confirmado si funciona la línea telefónica.','La causa de la interrupción no está confirmada.']};
}
export function draft(scenario, correction){if(correction==='checked')return scenario==='outage'?'El sistema de citas no está disponible. El proveedor confirmó que el correo reportado era legítimo. Esto no determina la causa de la interrupción ni si hubo acceso a registros. La clínica verificará los próximos pasos antes de comunicar nuevas indicaciones.':'El proveedor confirmó que el correo de restablecimiento reportado era legítimo. Esta verificación se refiere solo al correo; no determina si hubo acceso a registros. La clínica verificará los próximos pasos antes de comunicar nuevas indicaciones.';return scenario==='outage'?'El sistema de citas no está disponible. Se contactó al proveedor técnico y esperamos su respuesta. La causa y el posible acceso a registros aún no se conocen. La clínica verificará los próximos pasos antes de comunicar nuevas indicaciones.':'Se recibió un reporte sobre un correo de restablecimiento. La clínica está revisando la información con su proveedor técnico. No se ha establecido la causa ni si hubo acceso a registros. Se verificarán los próximos pasos antes de comunicar nuevas indicaciones.';}
export function gate(s){if(s.primary!=='yes'&&s.backup!=='yes')return 'Laura y Carlos no están disponibles. No puedes aprobar este mensaje todavía. Conserva el reporte y busca al proveedor técnico en el directorio conocido de la clínica para revisar la falla. Para autorizar la comunicación, espera a Laura o Carlos. Este ensayo no contacta a nadie.';if(!s.channel)return 'Revisa el contacto seleccionado en el directorio conocido de la clínica y marca «Comprobé el contacto». CLARA no comprueba si la línea funciona.';if(!s.review)return 'Revisa el borrador y marca la revisión.';return '';}
export function approver(s){return s.primary==='yes'?'Laura (principal ficticia)':'Carlos (suplente ficticio)';}
export function margin(vals){const max=[1000000,1000,100000,1000000,1000000];if(vals.length!==5||vals.some((v,i)=>v===''||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>max[i]))return null;const [p,h,r,s,o]=vals.map(Number);return p-h*r-s-o;}
export function canExport(s){return !gate(s)&&s.approved===s.revision;}
